static const char *secdat_mask_warning_policy_name(
    enum secdat_mask_warning_policy policy
)
{
    switch (policy) {
    case SECDAT_MASK_WARNINGS_ON:
        return "on";
    case SECDAT_MASK_WARNINGS_OFF:
        return "off";
    case SECDAT_MASK_WARNINGS_DEFAULT:
    default:
        return "default";
    }
}

