static int secdat_v2_domain_entry_key_access_available(const char *domain_id)
{
    struct secdat_domain_chain chain = {0};
    struct secdat_session_record record = {0};
    int available = 0;

    if (getenv("SECDAT_MASTER_KEY") != NULL && getenv("SECDAT_MASTER_KEY")[0] != '\0') {
        return 1;
    }
    if (secdat_domain_chain_from_id(domain_id, &chain) != 0) {
        return 0;
    }
    available = secdat_session_agent_status(&chain, &record) == 0;
    secdat_domain_chain_free(&chain);
    return available;
}

static int secdat_v2_encrypt_domain_entry_key(const char *domain_id, const char *key, char **encrypted_key)
{
    unsigned char *encrypted = NULL;
    size_t encrypted_length = 0;
    int status = 1;

    if (secdat_encrypt_value(domain_id, (const unsigned char *)key, strlen(key), &encrypted, &encrypted_length) != 0) {
        return 1;
    }
    if (secdat_hex_encode_bytes(encrypted, encrypted_length, encrypted_key) != 0) {
        goto cleanup;
    }
    status = 0;

cleanup:
    secdat_secure_clear(encrypted, encrypted_length);
    free(encrypted);
    return status;
}

static int secdat_v2_decrypt_domain_entry_key_with_access(
    const char *domain_id,
    struct secdat_v2_domain_entry_info *info,
    const struct secdat_key_access_options *access_options
)
{
    struct secdat_domain_chain chain = {0};
    unsigned char *encrypted = NULL;
    unsigned char *plaintext = NULL;
    size_t encrypted_length = 0;
    size_t plaintext_length = 0;
    int status = 1;

    if (info->has_key) {
        return 0;
    }
    if (info->key_visibility != SECDAT_KEY_VISIBILITY_UNLOCKED || !info->has_encrypted_key) {
        return 1;
    }
    if (secdat_hex_decode_bytes(info->encrypted_key, &encrypted, &encrypted_length) != 0) {
        return 1;
    }
    if (secdat_domain_chain_from_id(domain_id, &chain) != 0) {
        goto cleanup;
    }
    if (secdat_decrypt_value(
            &chain,
            encrypted,
            encrypted_length,
            &plaintext,
            &plaintext_length,
            access_options
        ) != 0) {
        goto cleanup;
    }
    if (plaintext_length == 0 || plaintext_length >= sizeof(info->key)
        || memchr(plaintext, '\0', plaintext_length) != NULL) {
        goto cleanup;
    }

    memcpy(info->key, plaintext, plaintext_length);
    info->key[plaintext_length] = '\0';
    if (!secdat_is_valid_env_name(info->key)) {
        info->key[0] = '\0';
        goto cleanup;
    }
    info->has_key = 1;
    status = 0;

cleanup:
    secdat_domain_chain_free(&chain);
    secdat_secure_clear(plaintext, plaintext_length);
    free(plaintext);
    secdat_secure_clear(encrypted, encrypted_length);
    free(encrypted);
    return status;
}

static int secdat_v2_decrypt_domain_entry_key(const char *domain_id, struct secdat_v2_domain_entry_info *info)
{
    return secdat_v2_decrypt_domain_entry_key_with_access(domain_id, info, NULL);
}

static int secdat_v2_domain_entry_key_is_covered_by_session(
    const char *domain_id,
    const struct secdat_v2_domain_entry_info *info,
    const struct secdat_key_list *covered_keys
)
{
    struct secdat_domain_chain chain = {0};
    struct secdat_session_record record = {0};
    struct secdat_key_access_options access_options = {0};
    struct secdat_v2_domain_entry_info candidate = *info;
    int covered = 0;

    if (covered_keys == NULL || covered_keys->count == 0
        || getenv("SECDAT_MASTER_KEY") == NULL || getenv("SECDAT_MASTER_KEY")[0] == '\0') {
        return 0;
    }
    if (secdat_domain_chain_from_id(domain_id, &chain) != 0
        || secdat_session_agent_get(&chain, &record) != 0) {
        goto cleanup;
    }
    access_options.master_key_override = record.master_key;
    access_options.quiet_auth_failure = 1;
    if (secdat_v2_decrypt_domain_entry_key_with_access(domain_id, &candidate, &access_options) == 0) {
        covered = secdat_key_list_contains(covered_keys, candidate.key);
    }

cleanup:
    secdat_secure_clear(record.master_key, strlen(record.master_key));
    secdat_domain_chain_free(&chain);
    return covered;
}

static int secdat_v2_domain_entry_key_matches(
    const char *domain_id,
    struct secdat_v2_domain_entry_info *info,
    const char *key,
    int require_key_access,
    int *matches
)
{
    *matches = 0;
    if (info->key_visibility == SECDAT_KEY_VISIBILITY_ALWAYS) {
        *matches = info->has_key && strcmp(info->key, key) == 0;
        return 0;
    }
    if (info->key_visibility != SECDAT_KEY_VISIBILITY_UNLOCKED) {
        return 1;
    }
    if (!secdat_v2_domain_entry_key_access_available(domain_id)) {
        if (require_key_access) {
            return secdat_v2_decrypt_domain_entry_key(domain_id, info);
        }
        return 0;
    }
    if (secdat_v2_decrypt_domain_entry_key(domain_id, info) != 0) {
        return 1;
    }
    *matches = strcmp(info->key, key) == 0;
    return 0;
}

static int secdat_collect_v2_visible_keys(
    const char *domain_id,
    const char *store_name,
    const struct secdat_key_list *covered_keys,
    struct secdat_key_list *keys
)
{
    char domain_entries_dir[PATH_MAX];
    char entry_path[PATH_MAX];
    struct secdat_key_list entry_ids = {0};
    struct secdat_v2_domain_entry_info info;
    size_t index;
    int status = 1;

    if (secdat_v2_domain_entries_dir(domain_id, store_name, domain_entries_dir, sizeof(domain_entries_dir)) != 0
        || secdat_collect_directory_keys(domain_entries_dir, ".dent", &entry_ids) != 0) {
        goto cleanup;
    }
    if (entry_ids.count > 1) {
        qsort(entry_ids.items, entry_ids.count, sizeof(*entry_ids.items), secdat_compare_strings);
    }

    for (index = 0; index < entry_ids.count; index += 1) {
        if (secdat_build_v2_domain_entry_path(domain_id, store_name, entry_ids.items[index], entry_path, sizeof(entry_path)) != 0) {
            goto cleanup;
        }
        if (secdat_read_v2_domain_entry_info(entry_path, entry_ids.items[index], &info) != 0) {
            fprintf(stderr, _("invalid v2 domain entry: %s\n"), entry_ids.items[index]);
            goto cleanup;
        }
        if (info.key_visibility == SECDAT_KEY_VISIBILITY_ALWAYS
            && info.has_key
            && covered_keys != NULL
            && secdat_key_list_contains(covered_keys, info.key)) {
            continue;
        }
        if (info.key_visibility == SECDAT_KEY_VISIBILITY_UNLOCKED) {
            if (secdat_v2_domain_entry_key_is_covered_by_session(domain_id, &info, covered_keys)) {
                continue;
            }
            if (!secdat_v2_domain_entry_key_access_available(domain_id)) {
                continue;
            }
            if (secdat_v2_decrypt_domain_entry_key(domain_id, &info) != 0) {
                fprintf(stderr, _("invalid v2 domain entry: %s\n"), entry_ids.items[index]);
                goto cleanup;
            }
        }
        if (info.has_key
            && (covered_keys == NULL || !secdat_key_list_contains(covered_keys, info.key))) {
            if (secdat_key_list_append(keys, info.key) != 0) {
                goto cleanup;
            }
        }
    }

    status = 0;

cleanup:
    secdat_key_list_free(&entry_ids);
    return status;
}

static int secdat_lookup_v2_domain_entry_internal(
    const char *domain_id,
    const char *store_name,
    const char *key,
    struct secdat_v2_domain_entry_info *info,
    char *entry_path,
    size_t entry_path_size,
    int require_authoritative_absence
)
{
    char domain_entries_dir[PATH_MAX];
    struct secdat_domain_chain chain = {0};
    struct secdat_key_list entry_ids = {0};
    size_t index;
    int key_access_available;
    int hidden_entries_inaccessible = 0;
    int found = 0;
    int status = SECDAT_V2_LOOKUP_ERROR;

    if (secdat_v2_domain_entries_dir(domain_id, store_name, domain_entries_dir, sizeof(domain_entries_dir)) != 0
        || secdat_collect_directory_keys(domain_entries_dir, ".dent", &entry_ids) != 0) {
        goto cleanup;
    }
    if (entry_ids.count > 1) {
        qsort(entry_ids.items, entry_ids.count, sizeof(*entry_ids.items), secdat_compare_strings);
    }

    key_access_available = secdat_v2_domain_entry_key_access_available(domain_id);
    for (index = 0; index < entry_ids.count; index += 1) {
        int matches = 0;

        if (secdat_build_v2_domain_entry_path(domain_id, store_name, entry_ids.items[index], entry_path, entry_path_size) != 0) {
            goto cleanup;
        }
        if (secdat_read_v2_domain_entry_info(entry_path, entry_ids.items[index], info) != 0) {
            fprintf(stderr, _("invalid v2 domain entry: %s\n"), entry_ids.items[index]);
            goto cleanup;
        }
        if (info->key_visibility == SECDAT_KEY_VISIBILITY_UNLOCKED && !key_access_available) {
            hidden_entries_inaccessible = 1;
            continue;
        }
        if (info->key_visibility == SECDAT_KEY_VISIBILITY_ALWAYS) {
            matches = info->has_key && strcmp(info->key, key) == 0;
        } else {
            if (secdat_v2_decrypt_domain_entry_key(domain_id, info) != 0) {
                fprintf(stderr, _("invalid v2 domain entry: %s\n"), entry_ids.items[index]);
                goto cleanup;
            }
            matches = strcmp(info->key, key) == 0;
        }
        if (matches) {
            found = 1;
            break;
        }
    }

    if (found) {
        status = SECDAT_V2_LOOKUP_FOUND;
    } else if (require_authoritative_absence && hidden_entries_inaccessible) {
        fprintf(
            stderr,
            _("missing SECDAT_MASTER_KEY and no active secdat session; run secdat unlock or export SECDAT_MASTER_KEY\n")
        );
        if (secdat_domain_chain_from_id(domain_id, &chain) == 0) {
            secdat_print_locked_read_guidance(&chain);
        }
        status = SECDAT_V2_LOOKUP_INACCESSIBLE;
    } else {
        status = SECDAT_V2_LOOKUP_ABSENT;
    }

cleanup:
    secdat_domain_chain_free(&chain);
    secdat_key_list_free(&entry_ids);
    return status;
}

static int secdat_lookup_v2_domain_entry(
    const char *domain_id,
    const char *store_name,
    const char *key,
    struct secdat_v2_domain_entry_info *info,
    char *entry_path,
    size_t entry_path_size
)
{
    return secdat_lookup_v2_domain_entry_internal(domain_id, store_name, key, info, entry_path, entry_path_size, 0);
}

static int secdat_lookup_v2_domain_entry_authoritative(
    const char *domain_id,
    const char *store_name,
    const char *key,
    struct secdat_v2_domain_entry_info *info,
    char *entry_path,
    size_t entry_path_size
)
{
    return secdat_lookup_v2_domain_entry_internal(domain_id, store_name, key, info, entry_path, entry_path_size, 1);
}

static const char *secdat_mask_record_kind_name(enum secdat_mask_record_kind kind)
{
    return kind == SECDAT_MASK_RECORD_CANONICAL ? "canonical" : "legacy";
}

static const char *secdat_mask_resolution_name(enum secdat_mask_resolution resolution)
{
    return resolution == SECDAT_MASK_RESOLUTION_BOUND ? "bound" : "ambiguous";
}

static const char *secdat_mask_state_name(enum secdat_mask_state state)
{
    switch (state) {
    case SECDAT_MASK_STATE_ACTIVE:
        return "active";
    case SECDAT_MASK_STATE_DORMANT:
        return "dormant";
    case SECDAT_MASK_STATE_ORPHANED:
        return "orphaned";
    default:
        return "orphaned";
    }
}

static void secdat_mask_view_list_free(struct secdat_mask_view_list *list)
{
    secdat_secure_clear(
        list->items,
        list->capacity * sizeof(*list->items)
    );
    free(list->items);
    memset(list, 0, sizeof(*list));
}

static int secdat_mask_view_list_append(
    struct secdat_mask_view_list *list,
    const struct secdat_mask_view *view
)
{
    struct secdat_mask_view *resized;
    size_t next_capacity;

    if (list->count == list->capacity) {
        next_capacity = list->capacity == 0 ? 8 : list->capacity * 2;
        resized = realloc(list->items, next_capacity * sizeof(*resized));
        if (resized == NULL) {
            fprintf(stderr, _("out of memory\n"));
            return 1;
        }
        list->items = resized;
        list->capacity = next_capacity;
    }
    list->items[list->count] = *view;
    list->count += 1;
    if (view->state_unknown) {
        list->visible_unknown_state_count += 1;
    }
    return 0;
}

static int secdat_compare_mask_views(const void *left_raw, const void *right_raw)
{
    const struct secdat_mask_view *left = left_raw;
    const struct secdat_mask_view *right = right_raw;
    int compared;

    compared = strcmp(left->key, right->key);
    if (compared != 0) {
        return compared;
    }
    if (left->record_kind != right->record_kind) {
        return left->record_kind < right->record_kind ? -1 : 1;
    }
    compared = strcmp(left->mask_chain_id, right->mask_chain_id);
    if (compared != 0) {
        return compared;
    }
    return strcmp(left->target_entry_id, right->target_entry_id);
}

static int secdat_build_v2_mask_path(
    const char *domain_id,
    const char *store_name,
    const char *target_entry_id,
    char *buffer,
    size_t size
)
{
    char masks_dir[PATH_MAX];

    if (secdat_v2_masks_dir(domain_id, store_name, masks_dir, sizeof(masks_dir)) != 0) {
        return 1;
    }
    if (snprintf(buffer, size, "%s/%s.mask", masks_dir, target_entry_id) >= (int)size) {
        fprintf(stderr, _("path is too long\n"));
        return 1;
    }
    return 0;
}

static const char *secdat_transaction_state_name(enum secdat_transaction_state state)
{
    switch (state) {
    case SECDAT_TRANSACTION_STAGING:
        return "staging";
    case SECDAT_TRANSACTION_PREPARED:
        return "prepared";
    case SECDAT_TRANSACTION_COMMITTING:
        return "committing";
    case SECDAT_TRANSACTION_COMMITTED:
        return "committed";
    default:
        return NULL;
    }
}

static int secdat_transaction_parse_state(
    const char *value,
    enum secdat_transaction_state *state
)
{
    if (strcmp(value, "staging") == 0) {
        *state = SECDAT_TRANSACTION_STAGING;
    } else if (strcmp(value, "prepared") == 0) {
        *state = SECDAT_TRANSACTION_PREPARED;
    } else if (strcmp(value, "committing") == 0) {
        *state = SECDAT_TRANSACTION_COMMITTING;
    } else if (strcmp(value, "committed") == 0) {
        *state = SECDAT_TRANSACTION_COMMITTED;
    } else {
        return 1;
    }
    return 0;
}

static const char *secdat_transaction_artifact_kind_name(
    enum secdat_transaction_artifact_kind kind
)
{
    switch (kind) {
    case SECDAT_TRANSACTION_ARTIFACT_MASK:
        return "mask";
    case SECDAT_TRANSACTION_ARTIFACT_TOMBSTONE:
        return "tombstone";
    case SECDAT_TRANSACTION_ARTIFACT_DOMAIN_ENTRY:
        return "domain-entry";
    case SECDAT_TRANSACTION_ARTIFACT_STATE_FILE:
        return "state-file";
    default:
        return NULL;
    }
}

static int secdat_transaction_parse_artifact_kind(
    const char *value,
    enum secdat_transaction_artifact_kind *kind
)
{
    if (strcmp(value, "mask") == 0) {
        *kind = SECDAT_TRANSACTION_ARTIFACT_MASK;
    } else if (strcmp(value, "tombstone") == 0) {
        *kind = SECDAT_TRANSACTION_ARTIFACT_TOMBSTONE;
    } else if (strcmp(value, "domain-entry") == 0) {
        *kind = SECDAT_TRANSACTION_ARTIFACT_DOMAIN_ENTRY;
    } else if (strcmp(value, "state-file") == 0) {
        *kind = SECDAT_TRANSACTION_ARTIFACT_STATE_FILE;
    } else {
        return 1;
    }
    return 0;
}

static int secdat_transaction_command_is_valid(const char *value)
{
    return strcmp(value, "mask") == 0
        || strcmp(value, "unmask") == 0
        || strcmp(value, "mask-rebind") == 0
        || strcmp(value, "set") == 0
        || strcmp(value, "cp") == 0
        || strcmp(value, "ln") == 0
        || strcmp(value, "rm") == 0
        || strcmp(value, "load") == 0
        || strcmp(value, "mv") == 0;
}

static int secdat_sha256_hex(
    const unsigned char *data,
    size_t length,
    char digest_hex[SECDAT_SHA256_HEX_LENGTH + 1]
)
{
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_length = 0;
    size_t index;

    if (EVP_Digest(data, length, digest, &digest_length, EVP_sha256(), NULL) != 1
        || digest_length != 32) {
        fprintf(stderr, _("failed to calculate transaction digest\n"));
        return 1;
    }
    for (index = 0; index < digest_length; index += 1) {
        snprintf(digest_hex + index * 2, 3, "%02x", digest[index]);
    }
    digest_hex[SECDAT_SHA256_HEX_LENGTH] = '\0';
    return 0;
}

static int secdat_transaction_digest_is_valid(const char *value)
{
    return value != NULL
        && strlen(value) == SECDAT_SHA256_HEX_LENGTH
        && secdat_hex_string_is_valid(value);
}

static int secdat_fsync_directory(const char *path)
{
    int descriptor = open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);

    if (descriptor < 0) {
        fprintf(stderr, _("failed to open directory for fsync: %s\n"), path);
        return 1;
    }
    if (fsync(descriptor) != 0) {
        fprintf(stderr, _("failed to fsync directory: %s\n"), path);
        close(descriptor);
        return 1;
    }
    if (close(descriptor) != 0) {
        fprintf(stderr, _("failed to close directory: %s\n"), path);
        return 1;
    }
    return 0;
}

static int secdat_fsync_parent_directory(const char *path)
{
    char parent[PATH_MAX];
    char *separator;

    if (secdat_copy_string(parent, sizeof(parent), path) != 0) {
        return 1;
    }
    separator = strrchr(parent, '/');
    if (separator == NULL || separator == parent) {
        fprintf(stderr, _("invalid path: %s\n"), path);
        return 1;
    }
    *separator = '\0';
    return secdat_fsync_directory(parent);
}

static int secdat_transaction_root_path(char *buffer, size_t size)
{
    char state_dir[PATH_MAX];

    if (secdat_state_dir(state_dir, sizeof(state_dir)) != 0) {
        return 1;
    }
    return snprintf(buffer, size, "%s/transactions", state_dir) >= (int)size;
}

static int secdat_transaction_validate_directory(const char *path)
{
    struct stat status;

    if (lstat(path, &status) != 0
        || !S_ISDIR(status.st_mode)
        || (status.st_mode & 077) != 0) {
        fprintf(stderr, _("invalid transaction directory: %s\n"), path);
        return 1;
    }
    return 0;
}

static int secdat_transaction_ensure_root(char *root, size_t root_size)
{
    char state_dir[PATH_MAX];

    if (secdat_state_dir(state_dir, sizeof(state_dir)) != 0
        || secdat_ensure_directory(state_dir, 0700) != 0
        || secdat_transaction_root_path(root, root_size) != 0
        || secdat_ensure_directory(root, 0700) != 0
        || secdat_fsync_directory(state_dir) != 0) {
        return 1;
    }
    return secdat_transaction_validate_directory(root);
}

static int secdat_transaction_open_lock(const char *root)
{
    char lock_path[PATH_MAX];
    const char *test_sync =
        getenv("SECDAT_TEST_TRANSACTION_LOCK_ATTEMPT_FD");
    struct stat status;
    int descriptor;

    if (snprintf(lock_path, sizeof(lock_path), "%s/lock", root) >= (int)sizeof(lock_path)) {
        fprintf(stderr, _("path is too long\n"));
        return -1;
    }
    descriptor = open(lock_path, O_CREAT | O_RDWR | O_CLOEXEC | O_NOFOLLOW, 0600);
    if (descriptor < 0
        || fstat(descriptor, &status) != 0
        || !S_ISREG(status.st_mode)
        || (status.st_mode & 077) != 0) {
        if (descriptor >= 0) {
            close(descriptor);
        }
        fprintf(stderr, _("invalid transaction lock\n"));
        return -1;
    }
    if (test_sync != NULL) {
        if (flock(descriptor, LOCK_EX | LOCK_NB) == 0) {
            if (secdat_test_signal_transaction_lock_attempt('A') != 0) {
                close(descriptor);
                return -1;
            }
            return descriptor;
        }
        if ((errno != EWOULDBLOCK && errno != EAGAIN)
            || secdat_test_signal_transaction_lock_attempt('B') != 0) {
            fprintf(stderr, _("failed to lock transactions\n"));
            close(descriptor);
            return -1;
        }
    }
    if (flock(descriptor, LOCK_EX) != 0) {
        fprintf(stderr, _("failed to lock transactions\n"));
        close(descriptor);
        return -1;
    }
    return descriptor;
}

static void secdat_transaction_reset(struct secdat_transaction *transaction)
{
    size_t index;

    for (index = 0; index < transaction->target_count; index += 1) {
        secdat_secure_clear(
            transaction->targets[index].before_data,
            transaction->targets[index].before_length
        );
        free(transaction->targets[index].before_data);
        secdat_secure_clear(
            transaction->targets[index].after_data,
            transaction->targets[index].after_length
        );
        free(transaction->targets[index].after_data);
    }
    free(transaction->targets);
    if (transaction->lock_fd >= 0) {
        (void)flock(transaction->lock_fd, LOCK_UN);
        close(transaction->lock_fd);
    }
    memset(transaction, 0, sizeof(*transaction));
    transaction->lock_fd = -1;
}

static int secdat_transaction_state_file_name_is_valid(const char *name)
{
    const char *cursor;
    const char *component;

    if (name == NULL
        || strncmp(name, "domains/", strlen("domains/")) != 0
        || name[0] == '/'
        || name[strlen(name) - 1] == '/'
        || strlen(name) >= PATH_MAX) {
        return 0;
    }
    component = name;
    for (cursor = name; ; cursor += 1) {
        unsigned char byte = (unsigned char)*cursor;

        if (byte == '/' || byte == '\0') {
            size_t length = (size_t)(cursor - component);

            if (length == 0
                || (length == 1 && component[0] == '.')
                || (length == 2
                    && component[0] == '.'
                    && component[1] == '.')) {
                return 0;
            }
            if (byte == '\0') {
                break;
            }
            component = cursor + 1;
            continue;
        }
        if (!(isalnum(byte)
                || byte == '.'
                || byte == '_'
                || byte == '-'
                || byte == '%')) {
            return 0;
        }
    }
    return 1;
}

static int secdat_transaction_target_path(
    enum secdat_transaction_artifact_kind kind,
    const char *domain_id,
    const char *store_name,
    const char *name,
    char *path,
    size_t path_size
)
{
    if (!secdat_domain_id_is_valid(domain_id)
        || store_name == NULL
        || store_name[0] == '\0') {
        return 1;
    }
    switch (kind) {
    case SECDAT_TRANSACTION_ARTIFACT_MASK:
        if (!secdat_uuid_is_valid(name)) {
            return 1;
        }
        return secdat_build_v2_mask_path(domain_id, store_name, name, path, path_size);
    case SECDAT_TRANSACTION_ARTIFACT_TOMBSTONE:
        if (!secdat_is_valid_env_name(name)) {
            return 1;
        }
        return secdat_build_tombstone_path(domain_id, store_name, name, path, path_size);
    case SECDAT_TRANSACTION_ARTIFACT_DOMAIN_ENTRY:
        if (!secdat_uuid_is_valid(name)) {
            return 1;
        }
        return secdat_build_v2_domain_entry_path(
            domain_id,
            store_name,
            name,
            path,
            path_size
        );
    case SECDAT_TRANSACTION_ARTIFACT_STATE_FILE: {
        char state_dir[PATH_MAX];

        if (!secdat_transaction_state_file_name_is_valid(name)
            || secdat_state_dir(state_dir, sizeof(state_dir)) != 0) {
            return 1;
        }
        return snprintf(path, path_size, "%s/%s", state_dir, name)
            >= (int)path_size;
    }
    default:
        return 1;
    }
}

static int secdat_transaction_read_target(
    const char *path,
    unsigned char **data,
    size_t *length,
    int *exists
)
{
    struct stat status;

    *data = NULL;
    *length = 0;
    *exists = 0;
    if (lstat(path, &status) != 0) {
        if (errno == ENOENT) {
            return 0;
        }
        fprintf(stderr, _("failed to inspect transaction target: %s\n"), path);
        return 1;
    }
    if (!S_ISREG(status.st_mode) || (status.st_mode & 077) != 0) {
        fprintf(stderr, _("invalid transaction target: %s\n"), path);
        return 1;
    }
    if (secdat_read_file(path, data, length) != 0) {
        return 1;
    }
    *exists = 1;
    return 0;
}

static int secdat_transaction_open_child_directory(
    int parent_fd,
    const char *name
)
{
    struct stat status;
    int descriptor = openat(
        parent_fd,
        name,
        O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW
    );

    if (descriptor < 0
        || fstat(descriptor, &status) != 0
        || !S_ISDIR(status.st_mode)
        || (status.st_mode & 022) != 0) {
        if (descriptor >= 0) {
            close(descriptor);
        }
        return -1;
    }
    return descriptor;
}

static int secdat_transaction_cleanup_target_temporaries(int descriptor)
{
    DIR *directory = fdopendir(dup(descriptor));
    struct dirent *entry;
    int removed = 0;

    if (directory == NULL) {
        return 1;
    }
    while ((entry = readdir(directory)) != NULL) {
        struct stat temporary_status;

        if (strncmp(entry->d_name, ".tmp.", 5) != 0
            || !secdat_uuid_is_valid(entry->d_name + 5)) {
            continue;
        }
        if (fstatat(
                descriptor,
                entry->d_name,
                &temporary_status,
                AT_SYMLINK_NOFOLLOW
            ) != 0
            || !S_ISREG(temporary_status.st_mode)
            || (temporary_status.st_mode & 077) != 0
            || unlinkat(descriptor, entry->d_name, 0) != 0) {
            closedir(directory);
            return 1;
        }
        removed = 1;
    }
    if (closedir(directory) != 0
        || (removed && fsync(descriptor) != 0)) {
        return 1;
    }
    return 0;
}

static int secdat_transaction_open_state_file_parent(
    const struct secdat_transaction_target *target,
    char *basename,
    size_t basename_size,
    int create_missing,
    int *parent_missing
)
{
    char state_dir[PATH_MAX];
    char relative[PATH_MAX];
    char *separator;
    char *component;
    char *saveptr = NULL;
    int descriptor = -1;
    int next_descriptor = -1;

    *parent_missing = 0;
    if (target->kind != SECDAT_TRANSACTION_ARTIFACT_STATE_FILE
        || !secdat_transaction_state_file_name_is_valid(target->name)
        || secdat_state_dir(state_dir, sizeof(state_dir)) != 0
        || secdat_copy_string(relative, sizeof(relative), target->name) != 0) {
        goto error;
    }
    separator = strrchr(relative, '/');
    if (separator == NULL
        || secdat_copy_string(
            basename,
            basename_size,
            separator + 1
        ) != 0) {
        goto error;
    }
    *separator = '\0';
    descriptor = open(
        state_dir,
        O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW
    );
    if (descriptor < 0) {
        goto error;
    }
    component = strtok_r(relative, "/", &saveptr);
    while (component != NULL) {
        next_descriptor = secdat_transaction_open_child_directory(
            descriptor,
            component
        );
        if (next_descriptor < 0
            && errno == ENOENT
            && create_missing) {
            if (mkdirat(descriptor, component, 0700) != 0
                || fsync(descriptor) != 0) {
                goto error;
            }
            next_descriptor = secdat_transaction_open_child_directory(
                descriptor,
                component
            );
        }
        if (next_descriptor < 0) {
            if (errno == ENOENT && !create_missing) {
                *parent_missing = 1;
                close(descriptor);
                return -1;
            }
            goto error;
        }
        close(descriptor);
        descriptor = next_descriptor;
        next_descriptor = -1;
        component = strtok_r(NULL, "/", &saveptr);
    }
    if (secdat_transaction_cleanup_target_temporaries(descriptor) != 0) {
        goto error;
    }
    return descriptor;

error:
    if (next_descriptor >= 0) {
        close(next_descriptor);
    }
    if (descriptor >= 0) {
        close(descriptor);
    }
    fprintf(stderr, _("invalid transaction target directory\n"));
    return -1;
}

static int secdat_transaction_open_target_parent(
    const struct secdat_transaction_target *target,
    char *basename,
    size_t basename_size
)
{
    char state_dir[PATH_MAX];
    char *escaped_store = NULL;
    char *escaped_name = NULL;
    int descriptor = -1;
    int next_descriptor = -1;
    const char *components[6];
    size_t component_count = 0;
    size_t index;

    if (secdat_state_dir(state_dir, sizeof(state_dir)) != 0
        || secdat_escape_component(target->store_name, &escaped_store) != 0) {
        goto cleanup;
    }
    components[component_count++] = "domains";
    components[component_count++] = "by-id";
    components[component_count++] = target->domain_id;
    components[component_count++] = "stores";
    components[component_count++] = escaped_store;
    if (target->kind == SECDAT_TRANSACTION_ARTIFACT_MASK) {
        components[component_count++] = "masks";
        if (snprintf(
                basename,
                basename_size,
                "%s.mask",
                target->name
            ) >= (int)basename_size) {
            goto cleanup;
        }
    } else if (target->kind == SECDAT_TRANSACTION_ARTIFACT_DOMAIN_ENTRY) {
        components[component_count++] = "domain-ent";
        if (snprintf(
                basename,
                basename_size,
                "%s.dent",
                target->name
            ) >= (int)basename_size) {
            goto cleanup;
        }
    } else if (target->kind == SECDAT_TRANSACTION_ARTIFACT_TOMBSTONE) {
        components[component_count++] = "tombstones";
        if (secdat_escape_component(target->name, &escaped_name) != 0
            || snprintf(
                basename,
                basename_size,
                "%s.tomb",
                escaped_name
            ) >= (int)basename_size) {
            goto cleanup;
        }
    } else {
        goto cleanup;
    }
    descriptor = open(
        state_dir,
        O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW
    );
    if (descriptor < 0) {
        goto cleanup;
    }
    for (index = 0; index < component_count; index += 1) {
        next_descriptor = secdat_transaction_open_child_directory(
            descriptor,
            components[index]
        );
        close(descriptor);
        descriptor = next_descriptor;
        next_descriptor = -1;
        if (descriptor < 0) {
            goto cleanup;
        }
    }
    if (secdat_transaction_cleanup_target_temporaries(descriptor) != 0) {
        close(descriptor);
        descriptor = -1;
        goto cleanup;
    }

cleanup:
    free(escaped_store);
    free(escaped_name);
    if (descriptor < 0) {
        fprintf(stderr, _("invalid transaction target directory\n"));
    }
    return descriptor;
}

static int secdat_transaction_read_live_target(
    const struct secdat_transaction_target *target,
    unsigned char **data,
    size_t *length,
    int *exists
)
{
    char basename[PATH_MAX];
    struct stat status;
    int parent_fd = -1;
    int descriptor = -1;
    int parent_missing = 0;
    unsigned char *buffer = NULL;
    size_t offset = 0;
    int result = 1;

    *data = NULL;
    *length = 0;
    *exists = 0;
    if (target->kind == SECDAT_TRANSACTION_ARTIFACT_STATE_FILE) {
        parent_fd = secdat_transaction_open_state_file_parent(
            target,
            basename,
            sizeof(basename),
            0,
            &parent_missing
        );
    } else {
        parent_fd = secdat_transaction_open_target_parent(
            target,
            basename,
            sizeof(basename)
        );
    }
    if (parent_fd < 0) {
        if (parent_missing) {
            result = 0;
        }
        goto cleanup;
    }
    descriptor = openat(
        parent_fd,
        basename,
        O_RDONLY | O_CLOEXEC | O_NOFOLLOW
    );
    if (descriptor < 0) {
        if (errno == ENOENT) {
            result = 0;
            goto cleanup;
        }
        goto cleanup;
    }
    if (fstat(descriptor, &status) != 0
        || !S_ISREG(status.st_mode)
        || (status.st_mode & 077) != 0
        || status.st_size < 0
        || (uintmax_t)status.st_size > SIZE_MAX) {
        goto cleanup;
    }
    buffer = malloc(status.st_size == 0 ? 1 : (size_t)status.st_size);
    if (buffer == NULL) {
        fprintf(stderr, _("out of memory\n"));
        goto cleanup;
    }
    while (offset < (size_t)status.st_size) {
        ssize_t count = read(
            descriptor,
            buffer + offset,
            (size_t)status.st_size - offset
        );

        if (count <= 0) {
            goto cleanup;
        }
        offset += (size_t)count;
    }
    *data = buffer;
    buffer = NULL;
    *length = offset;
    *exists = 1;
    result = 0;

cleanup:
    free(buffer);
    if (descriptor >= 0) {
        close(descriptor);
    }
    if (parent_fd >= 0) {
        close(parent_fd);
    }
    if (result != 0) {
        fprintf(stderr, _("failed to read transaction target\n"));
    }
    return result;
}

static int secdat_transaction_target_matches(
    const struct secdat_transaction_target *target,
    int after,
    int *matches
)
{
    unsigned char *data = NULL;
    size_t length = 0;
    int exists = 0;
    char digest[SECDAT_SHA256_HEX_LENGTH + 1];
    int expected_exists = after ? target->after_exists : target->before_exists;
    const char *expected_digest = after ? target->after_digest : target->before_digest;
    int status = 1;

    *matches = 0;
    if (secdat_transaction_read_live_target(
            target,
            &data,
            &length,
            &exists
        ) != 0) {
        goto cleanup;
    }
    if (exists != expected_exists) {
        status = 0;
        goto cleanup;
    }
    if (!exists) {
        *matches = 1;
        status = 0;
        goto cleanup;
    }
    if (secdat_sha256_hex(data, length, digest) != 0) {
        goto cleanup;
    }
    *matches = strcmp(digest, expected_digest) == 0;
    status = 0;

cleanup:
    secdat_secure_clear(data, length);
    free(data);
    return status;
}

static int secdat_transaction_blob_path(
    const struct secdat_transaction *transaction,
    size_t index,
    int after,
    char *path,
    size_t path_size
)
{
    return snprintf(
        path,
        path_size,
        "%s/%s.%04zu",
        transaction->operation_dir,
        after ? "after" : "before",
        index
    ) >= (int)path_size;
}

static int secdat_transaction_manifest_path(
    const struct secdat_transaction *transaction,
    char *path,
    size_t path_size
)
{
    return snprintf(path, path_size, "%s/journal", transaction->operation_dir)
        >= (int)path_size;
}

static int secdat_transaction_write_manifest(struct secdat_transaction *transaction)
{
    json_t *root = NULL;
    json_t *targets = NULL;
    char journal_path[PATH_MAX];
    char *json_text = NULL;
    unsigned char *payload = NULL;
    size_t payload_length = 0;
    size_t payload_buffer_size;
    size_t index;
    int written;
    int status = 1;

    root = json_object();
    targets = json_array();
    if (root == NULL || targets == NULL
        || json_object_set_new(root, "version", json_integer(1)) != 0
        || json_object_set_new(root, "operation_id", json_string(transaction->operation_id)) != 0
        || json_object_set_new(root, "command", json_string(transaction->command)) != 0
        || json_object_set_new(root, "owner_domain_id", json_string(transaction->owner_domain_id)) != 0
        || json_object_set_new(root, "owner_store", json_string(transaction->owner_store_name)) != 0
        || json_object_set_new(
            root,
            "state",
            json_string(secdat_transaction_state_name(transaction->state))
        ) != 0) {
        goto cleanup;
    }
    for (index = 0; index < transaction->target_count; index += 1) {
        const struct secdat_transaction_target *target = &transaction->targets[index];
        json_t *item = json_object();

        if (item == NULL
            || json_object_set_new(item, "domain_id", json_string(target->domain_id)) != 0
            || json_object_set_new(item, "store", json_string(target->store_name)) != 0
            || json_object_set_new(
                item,
                "kind",
                json_string(secdat_transaction_artifact_kind_name(target->kind))
            ) != 0
            || json_object_set_new(item, "name", json_string(target->name)) != 0
            || json_object_set_new(
                item,
                "before",
                json_string(target->before_exists ? target->before_digest : "absent")
            ) != 0
            || json_object_set_new(
                item,
                "after",
                json_string(target->after_exists ? target->after_digest : "absent")
            ) != 0) {
            json_decref(item);
            goto cleanup;
        }
        if (json_array_append(targets, item) != 0) {
            json_decref(item);
            goto cleanup;
        }
        json_decref(item);
    }
    if (json_object_set(root, "targets", targets) != 0) {
        goto cleanup;
    }
    json_decref(targets);
    targets = NULL;
    json_text = json_dumps(root, JSON_COMPACT | JSON_SORT_KEYS);
    if (json_text == NULL) {
        goto cleanup;
    }
    payload_length = strlen(secdat_transaction_magic) + 1 + strlen(json_text) + 1;
    payload_buffer_size = payload_length + 1;
    payload = malloc(payload_buffer_size);
    if (payload == NULL) {
        fprintf(stderr, _("out of memory\n"));
        goto cleanup;
    }
    written = snprintf(
        (char *)payload,
        payload_buffer_size,
        "%s\n%s\n",
        secdat_transaction_magic,
        json_text
    );
    if (written < 0 || (size_t)written != payload_length
        || secdat_transaction_manifest_path(
            transaction,
            journal_path,
            sizeof(journal_path)
        ) != 0
        || secdat_atomic_write_file(journal_path, payload, payload_length) != 0
        || secdat_fsync_directory(transaction->operation_dir) != 0) {
        goto cleanup;
    }
    status = 0;

cleanup:
    json_decref(targets);
    json_decref(root);
    free(json_text);
    secdat_secure_clear(payload, payload_length);
    free(payload);
    return status;
}

static int secdat_transaction_append_target(
    struct secdat_transaction *transaction,
    enum secdat_transaction_artifact_kind kind,
    const char *domain_id,
    const char *store_name,
    const char *name,
    const unsigned char *expected_before_data,
    size_t expected_before_length,
    int expected_before_exists,
    const unsigned char *after_data,
    size_t after_length,
    int after_exists
)
{
    struct secdat_transaction_target target;
    struct secdat_transaction_target *resized;
    unsigned char *live_before_data = NULL;
    size_t live_before_length = 0;
    int live_before_exists = 0;
    size_t next_capacity;
    size_t index;

    if (transaction->target_count >= SECDAT_TRANSACTION_MAX_TARGETS) {
        fprintf(stderr, _("transaction has too many targets\n"));
        return 1;
    }
    if (kind == SECDAT_TRANSACTION_ARTIFACT_DOMAIN_ENTRY
        && (!expected_before_exists
            || !after_exists
            || expected_before_length != after_length
            || CRYPTO_memcmp(
                expected_before_data,
                after_data,
                expected_before_length
            ) != 0)) {
        fprintf(stderr, _("invalid transaction validation target\n"));
        return 1;
    }
    memset(&target, 0, sizeof(target));
    target.kind = kind;
    target.after_exists = after_exists;
    if (secdat_copy_string(target.domain_id, sizeof(target.domain_id), domain_id) != 0
        || secdat_copy_string(
            target.store_name,
            sizeof(target.store_name),
            secdat_effective_store_name(store_name)
        ) != 0
        || secdat_copy_string(target.name, sizeof(target.name), name) != 0
        || secdat_transaction_target_path(
            kind,
            target.domain_id,
            target.store_name,
            target.name,
            target.path,
            sizeof(target.path)
        ) != 0
        || secdat_transaction_read_live_target(
            &target,
            &live_before_data,
            &live_before_length,
            &live_before_exists
        ) != 0) {
        goto error;
    }
    if (live_before_exists != expected_before_exists
        || (live_before_exists
            && (live_before_length != expected_before_length
                || CRYPTO_memcmp(
                    live_before_data,
                    expected_before_data,
                    expected_before_length
                ) != 0))) {
        fprintf(stderr, _("transaction changed since plan\n"));
        goto error;
    }
    target.before_exists = expected_before_exists;
    if (expected_before_exists) {
        target.before_data = malloc(
            expected_before_length == 0 ? 1 : expected_before_length
        );
        if (target.before_data == NULL) {
            fprintf(stderr, _("out of memory\n"));
            goto error;
        }
        if (expected_before_length > 0) {
            memcpy(
                target.before_data,
                expected_before_data,
                expected_before_length
            );
        }
        target.before_length = expected_before_length;
    }
    for (index = 0; index < transaction->target_count; index += 1) {
        if (strcmp(transaction->targets[index].path, target.path) == 0) {
            fprintf(stderr, _("duplicate transaction target\n"));
            goto error;
        }
    }
    if (target.before_exists
        && secdat_sha256_hex(
            target.before_data,
            target.before_length,
            target.before_digest
        ) != 0) {
        goto error;
    }
    if (after_exists) {
        target.after_data = malloc(after_length == 0 ? 1 : after_length);
        if (target.after_data == NULL) {
            fprintf(stderr, _("out of memory\n"));
            goto error;
        }
        if (after_length > 0) {
            memcpy(target.after_data, after_data, after_length);
        }
        target.after_length = after_length;
        if (secdat_sha256_hex(
                target.after_data,
                target.after_length,
                target.after_digest
            ) != 0) {
            goto error;
        }
    }
    if (transaction->target_count == transaction->target_capacity) {
        next_capacity = transaction->target_capacity == 0
            ? 4
            : transaction->target_capacity * 2;
        resized = realloc(transaction->targets, next_capacity * sizeof(*resized));
        if (resized == NULL) {
            fprintf(stderr, _("out of memory\n"));
            goto error;
        }
        transaction->targets = resized;
        transaction->target_capacity = next_capacity;
    }
    transaction->targets[transaction->target_count] = target;
    transaction->target_count += 1;
    secdat_secure_clear(live_before_data, live_before_length);
    free(live_before_data);
    return 0;

error:
    secdat_secure_clear(live_before_data, live_before_length);
    free(live_before_data);
    secdat_secure_clear(target.before_data, target.before_length);
    free(target.before_data);
    secdat_secure_clear(target.after_data, target.after_length);
    free(target.after_data);
    return 1;
}

static void secdat_transaction_fault_inject(const char *boundary)
{
    const char *requested = getenv("SECDAT_TEST_TRANSACTION_CRASH_AFTER");

    if (requested != NULL && strcmp(requested, boundary) == 0) {
        _exit(86);
    }
}

static int secdat_test_synchronize_mask_plan(void)
{
    const char *value = getenv("SECDAT_TEST_MASK_PLAN_SYNC_FD");
    char *end = NULL;
    long parsed;
    unsigned char signal = 'R';
    ssize_t result;

    if (value == NULL) {
        return 0;
    }
    errno = 0;
    parsed = strtol(value, &end, 10);
    if (errno != 0
        || end == value
        || *end != '\0'
        || parsed < 3
        || parsed > INT_MAX) {
        fprintf(stderr, "invalid test mask plan synchronization fd\n");
        return 1;
    }
    do {
        result = write((int)parsed, &signal, sizeof(signal));
    } while (result < 0 && errno == EINTR);
    if (result != (ssize_t)sizeof(signal)) {
        fprintf(stderr, "failed to signal prepared test mask plan\n");
        return 1;
    }
    do {
        result = read((int)parsed, &signal, sizeof(signal));
    } while (result < 0 && errno == EINTR);
    if (result != (ssize_t)sizeof(signal) || signal != 'G') {
        fprintf(stderr, "failed to resume prepared test mask plan\n");
        return 1;
    }
    return 0;
}

